import random
import ipaddress
import string

# Target: generate a bytes buffer that fuzzer will use for FUZZ_PARAM_STR in lcc_server_create
# The stub calls FUZZ_PARAM_STR() twice: node (hostname/IP) and service (service/port).
# So we craft a buffer that can be split by the harness to produce two valid strings.
# We will pack them as: node\0service\0 and include a variety of valid forms.

MAX_SIZE = 4096

HOST_LABEL_CHARS = string.ascii_letters + string.digits + "-"


def _rand_hostname(rng: random.Random) -> str:
    # Generate a valid hostname/FQDN with 1-4 labels, each 1-63 chars, total <= 253
    num_labels = rng.randint(1, 4)
    labels = []
    for i in range(num_labels):
        # Ensure label doesn't start or end with hyphen
        length = rng.randint(1, min(20, 63))
        if length == 1:
            labels.append(rng.choice(string.ascii_lowercase + string.digits))
            continue
        mid_len = length - 2
        start = rng.choice(string.ascii_lowercase + string.digits)
        mid = ''.join(rng.choice(HOST_LABEL_CHARS) for _ in range(mid_len)) if mid_len > 0 else ''
        end = rng.choice(string.ascii_lowercase + string.digits)
        labels.append(start + mid + end)
    return '.'.join(labels)


def _rand_ipv4(rng: random.Random) -> str:
    # Prefer common private ranges and edge values
    choices = [
        (10, rng.randint(0, 255), rng.randint(0, 255), rng.randint(1, 254)),
        (172, rng.randint(16, 31), rng.randint(0, 255), rng.randint(1, 254)),
        (192, 168, rng.randint(0, 255), rng.randint(1, 254)),
        (127, 0, 0, rng.randint(1, 255)),
        (rng.randint(1, 223), rng.randint(0, 255), rng.randint(0, 255), rng.randint(1, 254)),
    ]
    a, b, c, d = rng.choice(choices)
    return f"{a}.{b}.{c}.{d}"


def _rand_ipv6(rng: random.Random) -> str:
    # Generate normal or compressed IPv6, sometimes with IPv4 tail
    mode = rng.choice(['full', 'compressed', 'v4mapped'])
    if mode == 'v4mapped':
        ipv4 = _rand_ipv4(rng)
        # Use ::ffff:0:0/96 style or generic ::1:2 form
        prefix = rng.choice(['::ffff:', '::'])
        return f"{prefix}{ipv4}"
    elif mode == 'full':
        hextets = [f"{rng.randint(0, 0xFFFF):x}" for _ in range(8)]
        return ':'.join(hextets)
    else:
        # compressed: create some zeros and compress with :: once
        hextets = [rng.randint(0, 0xFFFF) for _ in range(8)]
        # introduce a run of zeros
        if rng.random() < 0.8:
            i = rng.randint(0, 6)
            run = rng.randint(1, 7 - i)
            for k in range(i, i + run):
                hextets[k] = 0
        # format and compress using ipaddress for correctness
        addr = ipaddress.IPv6Address(int(''.join(f"{h:04x}" for h in hextets), 16))
        return addr.compressed


def _rand_service(rng: random.Random) -> str:
    # Valid service strings: numeric ports or well-known names
    if rng.random() < 0.6:
        # numeric port in range 1-65535, bias to collectd default 25826
        biased = [25826, 80, 443, 53, 123, 514, 22, 25, 110, 995]
        if rng.random() < 0.5:
            return str(rng.choice(biased))
        return str(rng.randint(1, 65535))
    else:
        names = [
            'collectd', 'http', 'https', 'ntp', 'dns', 'syslog', 'ssh', 'smtp', 'imap', 'pop3',
            'snmp', 'mysql', 'postgres', 'redis', 'memcached'
        ]
        return rng.choice(names)


def _rand_node(rng: random.Random) -> str:
    kind = rng.choices(['hostname', 'ipv4', 'ipv6', 'bracket_ipv6'], weights=[4, 3, 3, 1])[0]
    if kind == 'hostname':
        return _rand_hostname(rng)
    elif kind == 'ipv4':
        return _rand_ipv4(rng)
    elif kind == 'ipv6':
        return _rand_ipv6(rng)
    else:
        # bracketed IPv6 literal, sometimes used in configs
        return f"[{_rand_ipv6(rng)}]"


def _assemble(node: str, service: str) -> bytes:
    # Pack as node\0service\0 which are typical for two FUZZ_PARAM_STR pulls
    data = node.encode('utf-8') + b"\x00" + service.encode('utf-8') + b"\x00"
    return data[:MAX_SIZE]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create multiple variants and pick one to offer diversity across seeds
    variant = rng.random()

    if variant < 0.15:
        # Exact collectd default port with common multicast/group targets
        node = rng.choice(['239.192.74.66', 'ff18::efc0:4a42', '::1', '127.0.0.1'])
        service = '25826'
    elif variant < 0.30:
        # FQDN with multiple labels
        node = _rand_hostname(rng)
        service = _rand_service(rng)
    elif variant < 0.55:
        # IPv4 with biased private ranges
        node = _rand_ipv4(rng)
        service = _rand_service(rng)
    elif variant < 0.80:
        # IPv6 variants
        node = _rand_ipv6(rng)
        service = _rand_service(rng)
    else:
        # Bracketed IPv6 literal and named service
        node = f"[{_rand_ipv6(rng)}]"
        service = _rand_service(rng)

    buf = _assemble(node, service)
    # Ensure under limit and non-empty
    if not buf or len(buf) > MAX_SIZE:
        # Fallback sane default
        buf = _assemble('127.0.0.1', '25826')
    return buf

import random
import string
from typing import List

# Generator for valid-looking network interface names to feed FUZZ_PARAM_STR in
# the lcc_server_set_interface fuzzer stub.
#
# Notes:
# - Interface names are ASCII, null-terminated in C usage; here we emit bytes of
#   the string without a trailing NUL; the harness typically appends it when
#   converting to C string (std::string::c_str()).
# - Common patterns per OS families are included to exercise typical parsing:
#   * Linux: eth0, ens33, enp3s0, wlan0, wlp2s0, lo, br0, bond0, tap0, tun0, virbr0,
#            docker0, vethXXXX, ppp0, sit0, ip6tnl0, dummy0, team0, ib0, can0
#   * BSD/macOS: en0, en1, bridge0, gif0, gre0, lo0, p2p0, awdl0, utun0, ap1
#   * Windows: Ethernet, Local Area Connection, Wi-Fi, vEthernet (Default Switch)
# - We also generate randomized but valid-looking names within typical length
#   limits (Linux IFNAMSIZ is commonly 16 incl. NUL, so up to 15 chars visible).
# - We avoid control chars and keep under 64 bytes overall; total buffer <= 4096.

MAX_VISIBLE_LEN = 15  # conservative for Linux IFNAMSIZ-1

COMMON_NAMES: List[str] = [
    # Linux
    "lo", "eth0", "eth1", "ens33", "enp3s0", "enp0s31f6", "wlan0", "wlan1",
    "wlp2s0", "br0", "bond0", "team0", "docker0", "virbr0", "tun0", "tap0",
    "veth0", "vethabcd", "ppp0", "sit0", "ip6tnl0", "dummy0", "ib0", "can0",
    # BSD/macOS
    "lo0", "en0", "en1", "en5", "bridge0", "gif0", "gre0", "awdl0", "utun0", "p2p0", "ap1",
    # Windows common display names (driver may accept as friendly name)
    "Ethernet", "Wi-Fi", "Local Area Connection", "vEthernet (Default Switch)",
]

# Prefix patterns and randomizers for Linux-style persistent naming
PREFIX_PATTERNS = [
    ("eth", lambda r: str(r.randint(0, 9))),
    ("wlan", lambda r: str(r.randint(0, 9))),
    ("br", lambda r: str(r.randint(0, 9))),
    ("bond", lambda r: str(r.randint(0, 9))),
    ("team", lambda r: str(r.randint(0, 9))),
    ("tun", lambda r: str(r.randint(0, 9))),
    ("tap", lambda r: str(r.randint(0, 9))),
    ("veth", lambda r: ''.join(r.choices(string.ascii_lowercase + string.digits, k=r.randint(1, 6)))),
    ("enp", lambda r: f"{r.randint(0,9)}s{r.randint(0,9)}"),  # e.g., enp3s0
    ("ens", lambda r: f"{r.randint(0,99)}"),
    ("wlp", lambda r: f"{r.randint(0,9)}s{r.randint(0,9)}"),
]

BSD_PREFIX_PATTERNS = [
    ("en", lambda r: str(r.randint(0, 9))),
    ("lo", lambda r: str(r.randint(0, 9))),
    ("bridge", lambda r: str(r.randint(0, 9))),
    ("gif", lambda r: str(r.randint(0, 9))),
    ("gre", lambda r: str(r.randint(0, 9))),
    ("utun", lambda r: str(r.randint(0, 9))),
    ("awdl", lambda r: str(r.randint(0, 9))),
]

WINDOWS_NAMES = [
    "Ethernet", "Ethernet 2", "Wi-Fi", "Wi-Fi 2", "Bluetooth Network Connection",
    "vEthernet (Default Switch)", "vEthernet (WSL)",
]


def clamp_visible(s: str) -> str:
    # Ensure length within conservative IFNAMSIZ-1
    if len(s) > MAX_VISIBLE_LEN:
        return s[:MAX_VISIBLE_LEN]
    return s


def random_linux_name(r: random.Random) -> str:
    prefix, gen = r.choice(PREFIX_PATTERNS)
    return clamp_visible(prefix + gen(r))


def random_bsd_name(r: random.Random) -> str:
    prefix, gen = r.choice(BSD_PREFIX_PATTERNS)
    return clamp_visible(prefix + gen(r))


def random_windows_name(r: random.Random) -> str:
    return clamp_visible(r.choice(WINDOWS_NAMES))


def random_custom_name(r: random.Random) -> str:
    # Generic pattern: [a-z]{2,5}[0-9]{0,2}(-[a-z0-9]{1,4})?
    base_len = r.randint(2, 5)
    base = ''.join(r.choices(string.ascii_lowercase, k=base_len))
    digits = ''.join(r.choices(string.digits, k=r.randint(0, 2)))
    if r.random() < 0.3:
        # optional suffix separated by dash (common in some virtual interfaces)
        suffix = '-' + ''.join(r.choices(string.ascii_lowercase + string.digits, k=r.randint(1, 4)))
    else:
        suffix = ''
    return clamp_visible(base + digits + suffix)


def pick_interface_name(r: random.Random) -> str:
    choice = r.random()
    if choice < 0.25:
        return clamp_visible(r.choice(COMMON_NAMES))
    elif choice < 0.5:
        return random_linux_name(r)
    elif choice < 0.7:
        return random_bsd_name(r)
    elif choice < 0.85:
        return random_windows_name(r)
    else:
        return random_custom_name(r)


def format_for_fuzzer(name: str) -> bytes:
    # The harness requests a single buffer that FUZZ_PARAM_STR will draw from.
    # Provide just the interface name as UTF-8 bytes. Avoid trailing NUL; std::string
    # manages lifetime and c_str() adds the NUL for the C API call.
    return name.encode('utf-8', errors='strict')


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    name = pick_interface_name(r)
    return format_for_fuzzer(name)

import random
import string
from typing import List

# Generator for collectd identifier strings
# Format: host/plugin[-plugin_instance]/type[-type_instance]
# Field constraints (practical/common):
# - host: may include letters, digits, dots, dashes, underscores, IPv6 in brackets, or IPv4
# - plugin, type: usually start with letter, can include letters, digits, underscore, dash
# - instances: similar, often allow dot and slash avoidance; we avoid '/'
# - Null-terminated C string is required by caller; fuzzer infra will pass as c_str(),
#   so we only ensure bytes contain ASCII characters.
# - We will generate a variety of valid shapes to exercise parser branches.

SAFE_CHARS = string.ascii_letters + string.digits + "._-"
LABEL_CHARS = string.ascii_lowercase + string.digits + "_-"

PLUGIN_NAMES = [
    "cpu", "memory", "disk", "interface", "load", "uptime",
    "df", "swap", "users", "tcpconns", "varnish", "nginx",
]
TYPE_NAMES = [
    "gauge", "derive", "counter", "absolute", "percent", "latency",
    "bytes", "time", "requests", "errors",
]
HOST_TEMPLATES = [
    "{hn}",            # simple hostname
    "{hn}.local",      # fqdn-like
    "{hn}.example.com",
    "{ipv4}",          # IPv4
    "[{ipv6}]",        # bracketed IPv6 form (often used in URLs; here for variety)
]


def rand_hostname(r: random.Random) -> str:
    hn_len = r.randint(3, 12)
    label = ''.join(r.choice(string.ascii_lowercase + string.digits) for _ in range(hn_len))
    ipv4 = '.'.join(str(r.randint(0, 255)) for _ in range(4))
    def rand_hextet():
        return ''.join(r.choice('0123456789abcdef') for _ in range(r.randint(1, 4)))
    ipv6 = ':'.join(rand_hextet() for _ in range(8))
    tmpl = r.choice(HOST_TEMPLATES)
    return tmpl.format(hn=label, ipv4=ipv4, ipv6=ipv6)


def rand_token(r: random.Random, base_chars: str, min_len: int = 1, max_len: int = 16) -> str:
    n = r.randint(min_len, max_len)
    return ''.join(r.choice(base_chars) for _ in range(n))


def rand_plugin(r: random.Random) -> str:
    if r.random() < 0.6:
        return r.choice(PLUGIN_NAMES)
    return rand_token(r, LABEL_CHARS)


def rand_type(r: random.Random) -> str:
    if r.random() < 0.6:
        return r.choice(TYPE_NAMES)
    return rand_token(r, LABEL_CHARS)


def maybe_instance(r: random.Random) -> str:
    # 60% include an instance
    if r.random() < 0.6:
        # instances sometimes numeric or with dots/underscores
        chars = LABEL_CHARS + "."
        return "-" + rand_token(r, chars)
    return ""


def build_identifier(r: random.Random) -> str:
    host = rand_hostname(r)

    # Sometimes introduce uppercase or dashes in plugin/type
    plugin = rand_plugin(r)
    if r.random() < 0.2:
        plugin = plugin.replace('_', '-')
    if r.random() < 0.2:
        plugin = plugin.upper()

    type_name = rand_type(r)
    if r.random() < 0.2:
        type_name = type_name.replace('_', '-')
    if r.random() < 0.2:
        type_name = type_name.upper()

    plugin_inst = maybe_instance(r)
    type_inst = maybe_instance(r)

    ident = f"{host}/{plugin}{plugin_inst}/{type_name}{type_inst}"

    # Occasionally add whitespace padding around fields which some parsers may trim
    if r.random() < 0.1:
        ident = ident.replace('/', ' / ')
    if r.random() < 0.05:
        ident = ident + "\n"  # trailing newline is common from user input

    return ident


def build_edge_case(r: random.Random) -> str:
    # Edge but valid cases to exercise branches
    cases: List[str] = []
    # Minimal tokens
    cases.append("h/p/t")
    # Longish fields within reasonable limits
    long = 'h' * r.randint(30, 60)
    cases.append(f"{long}/pluglong-{r.randint(0,9999)}/type-{r.randint(0,9999)}")
    # IPv6 host without brackets (still a string, parser may accept)
    ipv6 = ':'.join(''.join(r.choice('0123456789abcdef') for _ in range(4)) for _ in range(8))
    cases.append(f"{ipv6}/cpu-{r.randint(0,15)}/gauge-{r.randint(0,3)}")
    # Dotted host with multiple labels
    cases.append(f"node{r.randint(1,999)}.sub{r.randint(1,99)}.domain/df/percent-usage")
    # Uppercase mix
    cases.append("HOST/PLUGIN/TYPE")
    return r.choice(cases)


def make_identifier_bytes(r: random.Random) -> bytes:
    # Choose between typical and edge-case
    if r.random() < 0.8:
        s = build_identifier(r)
    else:
        s = build_edge_case(r)

    # Ensure ASCII-safe; filter to SAFE_CHARS and necessary separators
    allowed = set(SAFE_CHARS + "/-:\n []")
    s_filtered = ''.join(ch for ch in s if ch in allowed)
    if not s_filtered:
        s_filtered = "host/plugin/type"

    # Limit total size
    if len(s_filtered) > 4000:
        s_filtered = s_filtered[:4000]

    # Return as UTF-8 bytes; the fuzzer infra will hand c_str() to the API.
    return s_filtered.encode('utf-8')


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    return make_identifier_bytes(r)
